﻿const index = function () {

    const baseRoute = window.location.pathname;
    const createForm = $('#suggestion-form');
    let signedIn = false;
    let gridMode = false;
    let currentPage = 1;

    const totalRecords = Number($('#records').val());

    const datatable = {
        items: {
            object: null,
            getOptions: function (id) {
                return {
                    ajax: {
                        url: baseRoute,
                        data: function (data) {
                            data.handler = "items";
                            data.id = id;
                            data.library = $("#library-filter").val()
                        }
                    },
                    ordering: false,
                    info: false,
                    columns: [
                        {
                            data: "classification",
                            title: "Clasificación"
                        },
                        {
                            data: "barcode",
                            title: "Código de Barras"
                        },
                        {
                            data: "library",
                            title: "Ubicación"
                        },
                        {
                            data: "location",
                            title: "Sección"
                        },
                        {
                            data: "type",
                            title: "Tipo"
                        },
                        {
                            data: null,
                            title: "Estado",
                            render: function (data) {
                                if (signedIn && data.status == 'Disponible') {
                                    var html = ` Reservar `;
                                    return html;
                                } else
                                    return data.status;
                            }
                        },
                    ]
                }
            },
            load: function (id) {
                var options = this.getOptions(id);
                var table = $(`#table-record-${id}`).DataTable(options);
                table.on("click", ".btn-reservation", function () {
                    var id = $(this).data("id");
                    form.reservation.create(id, table);
                })
            },
            reload: function (id) {
                var options = this.getOptions(id);
                $(`#table-record-${id}`).DataTable(options);
            }
        }
    }

    const events = {
        onShow: function () {
            $(".btn-accordion").on('click', function () {
                const record = $(this).data('id');
                if ($(this).hasClass('loaded'))
                    return;

                datatable.items.load(record);
                $(this).addClass('loaded');
            });
        },
        filter: function () {
            $('.filter').on('click', function () {
                const type = $(this).data('filter');
                const value = $(this).data('val');

                const currentUrl = window.location.href;
                window.location.href = `${currentUrl}&${type}=${value}`;
            });

            $('#btn-apply-filters').on('click', function () {
                // const type = $(this).data('filter');
                // const value = $(this).data('val');
                //
                let currentUrl = new URL(window.location.href);

                $('input:checked').each(function () {
                    currentUrl.searchParams.append($(this).data('filter'), $(this).val());
                });

                const minYear = $("#min-year").val();
                if (minYear != null && minYear !== "")
                    currentUrl.searchParams.set("minYear", minYear);

                const maxYear = $("#max-year").val();
                if (maxYear != null && maxYear !== "")
                    currentUrl.searchParams.set("maxYear", maxYear);

                window.location.href = currentUrl.href;
            });
        },
        removeFilter: function () {
            $('.filter-badge').on('click', function () {
                const type = $(this).data('filter');
                const value = $(this).data('val');

                // if (type.indexOf('search') !== -1) {
                //     let url = window.location.href;
                //     url = url.replace(`&${type}.type=${value}`, '').replace(`${type}.type=${value}`, '');
                //     url = url.replace(`&${type}.text=${value}`, '').replace(`${type}.text=${value}`, '');
                //    
                //     let encoded = encodeURI(type);
                //     url = url.replace(`&${encoded}.type=${value}`, '').replace(`${encoded}.type=${value}`, '');
                //     url = url.replace(`&${encoded}.text=${value}`, '').replace(`${encoded}.text=${value}`, '');
                //     window.location.href = url;
                // } else
                window.location.href = window.location.href.replace(`&${type}=${value}`, '').replace(`${type}=${value}`, '');
            });
        },
        init: function () {
            /*this.onShow();*/
            this.filter();
            this.removeFilter();

            $('.ShowMore').on('click', function () {
                $(this).closest('.card').first('.list-group').find('.list-group-item:not(:visible):lt(5)').show();
            })

            $('.ShowLess').on('click', function () {
                $(this).closest('.card').first('.list-group').find('.list-group-item').hide();
                $(this).closest('.card').first('.list-group').find('.list-group-item:lt(5)').show();
            })

            $("#year-filter").ionRangeSlider({
                onChange: function (data) {
                    $("#min-year").val(data.from);
                    $("#max-year").val(data.to);
                }
            });

            $('input[type=radio][name=btnradio]').on('change', function () {
                if (this.value == 'list') {
                    gridMode = false;
                    biblios.load(currentPage);
                }
                else if (this.value == 'grid') {
                    gridMode = true;
                    biblios.load(currentPage);
                }
            });
        }
    }

    const form = {
        create: {
            object: createForm.validate({
                submitHandler: function (e) {
                    createForm.block();

                    $.ajax({
                        url: $(e).attr("action"),
                        type: "POST",
                        data: $(e).serialize()
                    })
                        .done(function () {
                            Swal.fire({
                                icon: 'success',
                                text: AkApp.Constants.Message.Success.Create,
                                confirmButtonText: 'Excelente',
                                allowOutsideClick: false,
                                customClass: {
                                    confirmButton: "btn btn-success",
                                },
                            })
                                .then((result) => {
                                    if (result.isConfirmed) {
                                        window.location = `/usuario/mis-sugerencias`;
                                    }
                                })
                        })
                        .fail(function (error) {
                            Swal.fire({
                                icon: 'error',
                                text: error.responseText ?? AkApp.Constants.Message.Error.Task,
                                customClass: {
                                    confirmButton: "btn btn-danger",
                                },
                            })
                        })
                        .always(function () {
                            createForm.unblock();
                        });
                }
            }),
            clear: function () {
                this.object.resetForm();
                createForm.trigger("reset");
            }
        },
        reservation: {
            create: function (id, table) {
                biblios.object.block();
                $.ajax({
                    url: `${baseRoute}?handler=createReservation`,
                    type: "POST",
                    data: {
                        itemId: id
                    }
                })
                    .done(function () {
                        table.ajax.reload(null, false);
                        Swal.fire({
                            icon: 'success',
                            text: "Se ha realizado su reserva. Por favor acérquese a la Biblioteca para realizar su préstamo.",
                            confirmButtonText: 'Excelente',
                            customClass: {
                                confirmButton: "btn btn-success",
                            },
                        });
                    })
                    .fail(function (error) {
                        Swal.fire({
                            icon: 'error',
                            text: error.responseText ?? AkApp.Constants.Message.Error.Task,
                            customClass: {
                                confirmButton: "btn btn-danger",
                            },
                        })
                    })
                    .always(function () {
                        biblios.object.unblock();
                    });
            }
        }
    }

    const biblios = {
        object: $("#biblio-container"),
        load: function (page = 1) {
            this.object.block();

            $("html, body").animate({ scrollTop: 0 });

            $.ajax({
                url: $(location).attr("href"),
                type: "GET",
                data: {
                    handler: "biblios",
                    page: page
                }
            })
                .done(function (data) {
                    var html = "";
                    if (data.records.length == 0) {
                        html = ` No se encontraron registros`
                        if (data.signed) {
                            html += ` ¿Desea registrar una sugerencia? `
                        }
                        html += ` `;
                    } else {
                        var paging = biblios.generatePaging(page, totalRecords);

                        html += paging;

                        if (gridMode) {

                            html += ' ';

                            $.each(data.records, function (index, element) {
                                var img = element.bookCover == "" || element.bookCover == null ? "/images/sin-tapa-libro.png" : `/archivos/descargar/${element.bookCover}`;

                                html += ` ${element.title} ${element.authorities ?? ""} Ejemplares (${element.items}) `;
                            });

                            html += ' ';
                        }
                        else {
                            $.each(data.records, function (index, element) {
                                var img = element.bookCover == "" || element.bookCover == null ? "/images/sin-tapa-libro.png" : `/archivos/descargar/${element.bookCover}`;
                                html += ` ${element.title} Autor(es): ${element.authorities ?? ""} Editorial: ${element.publisher ?? ""} Año de Publicación: ${element.publicationYear} Clasificación: ${element.classification ?? ""} Ejemplares: ${element.items} Detalle del registro / Ejemplares disponibles (${element.items}) Dimensión: ${element.dewey} ISBN/ISSN/DL: ${element.isbn}/${element.issn}/- Nota del Contenido: Clasificación Código de Barras Ubicación Sección Tipo Estado `;
                            });
                        }
                       
                        html += paging;
                    }

                    $('#biblio-container').html(html);

                    var instance = new Mark(document.querySelector('#biblio-container'));

                    instance.mark($('#search-filter').val(), {
                        "accuracy": {
                            "value": "exactly",
                            "limiters": [",", ".", ";"]
                        }
                    });

                    signedIn = data.signed;
                    events.onShow();
                    currentPage = page;
                })
                .fail(function (error) {
                    Swal.fire({
                        icon: 'error',
                        text: error.responseText ?? AkApp.Constants.Message.Error.Task,
                        customClass: {
                            confirmButton: "btn btn-danger",
                        },
                    })
                })
                .always(function () {
                    biblios.object.unblock();
                });
        },
        generatePaging: function (page, total) {
            var finalPage = Math.ceil(total / 20);
            if (finalPage <= 1) return '';

            var startIndex = Math.max(1, page - 4);
            var endIndex = Math.min(finalPage, page + 4);
            var html = [];
            html.push(' ');

            // First and Previous
            if (page === 1) {
                html.push(' « ');
                html.push(' ‹ ');
            } else {
                html.push(` « `);
                html.push(` ‹ `);
            }

            // Page numbers
            for (var i = startIndex; i <= endIndex; i++) {
                if (i === page) {
                    html.push(` ${i} `);
                } else {
                    html.push(` ${i} `);
                }
            }

            // Next and Last
            if (page === finalPage) {
                html.push(' › ');
                html.push(' » ');
            } else {
                html.push(` › `);
                html.push(` » `);
            }

            html.push(' ');
            return html.join('');
        }
    }

    return {
        init: function () {
            events.init();
            biblios.load();
        },
        loadData: function (page) {
            biblios.load(page);
        }
    }
}();

function AddParam(value, type) {
    let currentUrl = new URL(window.location.href);
    currentUrl.searchParams.append(type, value);
    window.location.href = currentUrl.href;
}

$(() => {
    index.init();
});
